// returns a 2 dimensional minmax normalized sample set generated by the image
// or nil if the image cound not be processed or does not exist
//
// the image is the negative image of the ImageToSampleSet() function
func ImageToSampleSetReverse(imagePath string, setSample func(x, y int, img *image.Image) bool) []*mat.VecDense {

	var img *image.Image = GetImage(imagePath)
	if img == nil {
		return nil
	}
	var samples []*mat.VecDense

	boundsX := (*img).Bounds().Dx()
	boundsY := (*img).Bounds().Dy()

	for x := range boundsX {
		for y := range boundsY {

			if setSample(x, y, img) {
				samples = append(samples, mat.NewVecDense(2, []float64{float64(x) / float64(boundsX), 1.0 - float64(y)/float64(boundsY)}))
			}
		}
	}

	scaler := Fit(samples, 0, 1)
	scaler.Transform(samples) // minmax normalize the data set

	return samples
}

// returns a 2 dimensional minmax normalized sample set generated by the image
// or nil if the image cound not be processed or does not exist
func ImageToSampleSet(imagePath string) []*mat.VecDense {

	var img *image.Image = GetImage(imagePath)
	if img == nil {
		return nil
	}
	var samples []*mat.VecDense

	boundsX := (*img).Bounds().Dx()
	boundsY := (*img).Bounds().Dy()

	for x := range boundsX {
		for y := range boundsY {
			r, _, _, a := (*img).At(x, y).RGBA()
			if rand.Float64() < float64(r)/float64(0xffff)*float64(a)/float64(0xffff) {
				samples = append(samples, mat.NewVecDense(2, []float64{float64(x) / float64(boundsX), 1.0 - float64(y)/float64(boundsY)}))
			}
		}
	}

	scaler := Fit(samples, 0, 1)
	scaler.Transform(samples) // minmax normalize the data set

	return samples
}

// filePath ...file path of a 3d model .ply file
//
// returns a minmax normalized sample set.
func PlyToSampleSet(filePath string) (vecs []*mat.VecDense, err error) {
	f, err := os.Open(filePath)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1024*1024), 1024*1024)

	var (
		nVertex     = -1
		inVertex    bool
		props       []string // property names of the vertex element, in order
		elemsBefore int      // elements declared before "vertex" (lines to skip)
		skipCounts  []int
	)

	// --- Header ---
	if !sc.Scan() || strings.TrimSpace(sc.Text()) != "ply" {
		return nil, fmt.Errorf("not a PLY file")
	}
	for sc.Scan() {
		fields := strings.Fields(sc.Text())
		if len(fields) == 0 {
			continue
		}
		switch fields[0] {
		case "format":
			if len(fields) < 2 || fields[1] != "ascii" {
				return nil, fmt.Errorf("only ASCII PLY supported, got %q", sc.Text())
			}
		case "element":
			if len(fields) < 3 {
				return nil, fmt.Errorf("bad element line: %q", sc.Text())
			}
			n, err := strconv.Atoi(fields[2])
			if err != nil {
				return nil, err
			}
			inVertex = fields[1] == "vertex"
			if inVertex {
				nVertex = n
			} else if nVertex < 0 {
				// element appearing before vertex: its lines come first in the body
				elemsBefore++
				skipCounts = append(skipCounts, n)
			}
		case "property":
			if inVertex {
				props = append(props, fields[len(fields)-1])
			}
		case "end_header":
			goto body
		}
	}
	return nil, fmt.Errorf("missing end_header")

body:
	if nVertex < 0 {
		return nil, fmt.Errorf("no vertex element found")
	}
	idx := map[string]int{"x": -1, "y": -1, "z": -1}
	for i, p := range props {
		if _, ok := idx[p]; ok {
			idx[p] = i
		}
	}
	for k, v := range idx {
		if v < 0 {
			return nil, fmt.Errorf("vertex property %q missing", k)
		}
	}

	// Skip data of elements declared before vertex (rare, but legal).
	for _, n := range skipCounts {
		for i := 0; i < n && sc.Scan(); i++ {
		}
	}

	// --- Vertex data ---
	pts := make([][3]float64, 0, nVertex)
	for len(pts) < nVertex && sc.Scan() {
		fields := strings.Fields(sc.Text())
		if len(fields) < len(props) {
			continue
		}
		var p [3]float64
		for d, name := range []string{"x", "y", "z"} {
			v, err := strconv.ParseFloat(fields[idx[name]], 64)
			if err != nil {
				return nil, fmt.Errorf("vertex %d: %v", len(pts), err)
			}
			p[d] = v
		}
		pts = append(pts, p)
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	if len(pts) != nVertex {
		return nil, fmt.Errorf("expected %d vertices, read %d", nVertex, len(pts))
	}
	vecs = toVecDense(pts)
	scaler := Fit(vecs, 0, 1)
	scaler.Transform(vecs) // minmax normalize the data set
	return vecs, nil
}

func toVecDense(pts [][3]float64) []*mat.VecDense {
	vecs := make([]*mat.VecDense, len(pts))
	for i, pt := range pts {
		slice := []float64{pt[0], pt[1], pt[2]}
		vecs[i] = mat.NewVecDense(3, slice)
	}
	return vecs
}

// Normalize centers the cloud and scales it uniformly into [-1, 1]
// (keeps the bunny's aspect ratio).
func NormalizeArr(pts [][3]float64) {
	var c [3]float64
	for _, p := range pts {
		for d := 0; d < len(p); d++ {
			c[d] += p[d]
		}
	}
	for d := 0; d < len(c); d++ {
		c[d] /= float64(len(pts))
	}
	maxAbs := 0.0
	for i := range pts {
		for d := 0; d < 3; d++ {
			pts[i][d] -= c[d]
			maxAbs = math.Max(maxAbs, math.Abs(pts[i][d]))
		}
	}
	if maxAbs > 0 {
		for i := range pts {
			for d := 0; d < 3; d++ {
				pts[i][d] /= maxAbs
			}
		}
	}
}

// returns a minmax normalized sample set.
func CSVNoHeaderToSampleSet(filepath string, dimensions int, logger *slog.Logger) (vecs []*mat.VecDense, err error) {
	file, err := os.OpenFile(filepath, os.O_CREATE|os.O_RDWR, 0644)
	if err != nil {
		util.LogError(logger, fmt.Sprintf("Could not open file: %s", filepath))
		return nil, fmt.Errorf("open file: %s failed.\n", filepath)
	}
	defer file.Close()

	csv, err := NewCSVFile(file, false, "\t", " \n\t")
	if err != nil {
		util.LogError(logger, "Could not create CSV object.")
		return nil, err
	}

	vecs = make([]*mat.VecDense, 0)
	var buf []float64

	buf, err = csv.ReadLine()
	for err == nil {
		vecs = append(vecs, mat.NewVecDense(dimensions, buf[:dimensions]))
		buf, err = csv.ReadLine()
	}

	scaler := Fit(vecs, 0, 1)
	scaler.Transform(vecs) // minmax normalize the data set

	return vecs, nil

}

func Normalize(vecs []*mat.VecDense) []*mat.VecDense {
	if len(vecs) == 0 {
		return vecs
	}

	normalized := make([]*mat.VecDense, len(vecs))
	max := make([]float64, vecs[0].Len())
	//get max components
	for dim := range vecs[0].Len() {
		max[dim] = util.MaxAny(
			func(elem, currMax *mat.VecDense) bool {
				return elem.AtVec(dim) > currMax.AtVec(dim)
			},
			vecs...,
		).AtVec(dim)
	}

	maxVec := mat.NewVecDense(len(max), max)
	for i, vec := range vecs {
		normalized[i] = mat.NewVecDense(vec.Len(), nil)
		normalized[i].DivElemVec(vec, maxVec)
	}

	return normalized
}
